import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Aggregate stats
    my_c = 0
    my_d = 0
    op_c = 0
    op_d = 0
    last_my = None
    last_op = None
    for me, op in history:
        if me == 'C':
            my_c += 1
        else:
            my_d += 1
        if op == 'C':
            op_c += 1
        else:
            op_d += 1
        last_my = me
        last_op = op

    rounds_left = 100 - n

    # Very early: be nice, but don't get stuck absorbing early defections.
    if n <= 2:
        if last_op == 'D':
            return 'D'
        return 'C'

    # Opponent appears unconditional cooperator: exploit but keep some C
    # to preserve cooperation if we misjudged (noise-free, so mostly D).
    if op_d == 0:
        # Never defected yet: from mid-game onward, exploit steadily.
        if n < 6:
            return 'C'
        if rounds_left <= 3:
            return 'D'
        # Occasionally give C to keep relationship if fragile.
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent appears unconditional defector: defect, with rare probes.
    if op_c == 0:
        if rounds_left <= 2:
            return 'D'
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Compute recent behaviour
    look = 8 if n >= 8 else n
    recent_op_d = 0
    recent_my_d = 0
    for i in range(n - look, n):
        if history[i][1] == 'D':
            recent_op_d += 1
        if history[i][0] == 'D':
            recent_my_d += 1

    # Current defection streak lengths
    op_run_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            op_run_d += 1
        else:
            break
    op_run_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            op_run_c += 1
        else:
            break
    my_run_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_run_d += 1
        else:
            break

    op_rate = op_c / float(n)

    # Detect periodic/alternating defection pattern in recent history.
    # If opponent switches often, don't chase; pick the best fixed response.
    if n >= 10:
        flips = 0
        for i in range(n - look + 1, n):
            if history[i][1] != history[i - 1][1]:
                flips += 1
        if flips >= look - 2 and 0.25 <= op_rate <= 0.75:
            # Opponent looks noisy/periodic. Defect more often; against
            # a 50/50 random, D gives (5+1)/2=3 vs C gives (3+0)/2=1.5.
            if rounds_left <= 4:
                return 'D'
            if rng.random() < 0.7:
                return 'D'
            return 'C'

    # Endgame: defect unless opponent is extremely cooperative and has
    # recently shown willingness to keep cooperating.
    if rounds_left <= 5:
        if op_rate > 0.9 and op_run_c >= 2 and n >= 10:
            # Likely a pure cooperator-ish; still defect on final round only.
            if rounds_left <= 1:
                return 'D'
            if rng.random() < 0.5:
                return 'D'
            return 'C'
        return 'D'

    # Opponent just defected.
    if last_op == 'D':
        # If opponent is generally cooperative and this is a lone defect,
        # forgive once to recover cooperation (maximum long-run reward).
        if op_rate >= 0.7 and op_run_d == 1:
            # But don't forgive repeatedly: check prior op move was C.
            if n >= 2 and history[-2][1] == 'C':
                return 'C'
        # Recuperate from long DD loops: if we've both been defecting a lot,
        # give a single C to attempt to unlock cooperation.
        if op_run_d >= 2 and my_run_d >= 2:
            if rng.random() < 0.4:
                return 'C'
            return 'D'
        return 'D'

    # Opponent just cooperated.
    # If we defected last round and opponent still cooperated, they may be
    # forgiving/unconditional; exploit lightly but not suicidally.
    if last_my == 'D':
        if op_rate >= 0.6 and op_run_c >= 2:
            # They keep rewarding our defections: keep going for the 5.
            if rounds_left > 3 and rng.random() < 0.65:
                return 'D'
            return 'C'
        # They cooperated after our D, likely forgiving: return to C.
        return 'C'

    # Both cooperated: default cooperate, occasional probe against suckers.
    if op_rate >= 0.85 and n >= 12 and rounds_left > 6:
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # Mixed opponent: mirror-with-forgiveness. Use TFT-ish if cooperative.
    if op_rate >= 0.5:
        return 'C'

    # Opponent is defecting more than half the time: lean D but probe.
    if rounds_left > 6 and rng.random() < 0.2:
        return 'C'
    return 'D'
